<div class="page-heading"><div><div class="eyebrow">MARCENARIA DE PRECISÃO</div><h1>Lista e plano de corte</h1><p>Peças por projeto, fitas de borda e aproveitamento estimado.</p></div><div class="page-actions"><button class="btn-aurora btn-outline-aurora" onclick="window.print()"><?=svg_icon('file',16)?> Imprimir plano</button></div></div>
<div class="panel panel-pad" style="margin-bottom:20px"><form method="get" class="form-grid"><input type="hidden" name="route" value="cuts"><div class="field"><label>Projeto</label><select name="project_id" onchange="this.form.submit()"><?php foreach($projects as $p):?><option value="<?=e($p['id'])?>" <?=$projectId==(int)$p['id']?'selected':''?>><?=e($p['title'])?></option><?php endforeach;?></select></div><div class="field"><label>Material / Chapa</label><select name="material_id" onchange="this.form.submit()"><?php foreach($boards as $b):?><option value="<?=e($b['id'])?>" <?=$materialId==(int)$b['id']?'selected':''?>><?=e($b['name'])?> (<?=e(qty($b['width_mm']))?>×<?=e(qty($b['height_mm']))?>)</option><?php endforeach;?></select></div></form></div>
<?php if(!$board || !$projectId):?><div class="panel panel-pad"><div class="empty">Cadastre um projeto e uma chapa com dimensões em Materiais para iniciar o plano de corte.</div></div><?php else:?>
<div class="grid-split" style="margin-bottom:20px"><div class="panel"><div class="panel-header"><h2>Peças para corte</h2><span class="tag"><?=count($pieces)?> tipos</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Identificação</th><th>Medidas</th><th>Qtd.</th><th>Veio</th><th>Fita (m)</th><th></th></tr></thead><tbody><?php foreach($pieces as $p):$fita=((int)$p['edge_top']+(int)$p['edge_bottom'])*(float)$p['width_mm']+((int)$p['edge_left']+(int)$p['edge_right'])*(float)$p['height_mm'];?><tr><td><strong><?=e($p['label'])?></strong></td><td><?=e(qty($p['width_mm']))?> × <?=e(qty($p['height_mm']))?> mm</td><td><?=e($p['quantity'])?></td><td><?=e(['free'=>'Livre','vertical'=>'Vertical','horizontal'=>'Horizontal'][$p['grain']]??$p['grain'])?></td><td><?=e(qty($fita*$p['quantity']/1000))?></td><td><?php if(allow(['production'])):?><form action="<?=e(url('cuts.delete'))?>" method="post" data-confirm="Remover esta peça?"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($p['id'])?>"><button class="btn-aurora btn-danger-soft btn-sm-aurora">Remover</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$pieces):?><tr><td colspan="6" class="empty">Adicione peças para visualizar o corte.</td></tr><?php endif;?></tbody></table></div><div class="summary-strip"><div><span class="mini-label">Fita de borda estimada</span><strong class="value"><?=e(number_format($edgeMeters,2,',','.'))?> m</strong></div><div><span class="mini-label">Tipos de peças</span><strong class="value"><?=count($pieces)?></strong></div><div><span class="mini-label">Peças totais</span><strong class="value"><?=array_sum(array_column($pieces,'quantity'))?></strong></div></div></div>
<div class="panel panel-pad"><h2>Adicionar peça</h2><p class="hint" style="margin-bottom:17px">Chapa: <?=e($board['name'])?> — <?=e(qty($board['width_mm']))?> × <?=e(qty($board['height_mm']))?> mm</p>
<?php if(allow(['production'])):?><form action="<?=e(url('cuts.save'))?>" method="post"><?=csrf_field()?><input type="hidden" name="_back" value="cuts"><input type="hidden" name="project_id" value="<?=e($projectId)?>"><input type="hidden" name="material_id" value="<?=e($materialId)?>"><div class="form-grid"><div class="field span-2"><label>Identificação *</label><input name="label" required placeholder="Ex.: Lateral armário superior"></div><div class="field"><label>Largura (mm) *</label><input name="width_mm" type="number" min="0.1" step="0.1" required></div><div class="field"><label>Altura (mm) *</label><input name="height_mm" type="number" min="0.1" step="0.1" required></div><div class="field"><label>Quantidade *</label><input name="quantity" type="number" min="1" max="500" step="1" value="1" required></div><div class="field"><label>Sentido do veio</label><select name="grain"><option value="free">Livre (rotação permitida)</option><option value="vertical">Vertical</option><option value="horizontal">Horizontal</option></select></div></div><label style="display:block;font-size:11px;margin-top:15px;color:#b8c5d7;font-weight:750">Aplicação de fita de borda</label><div style="display:flex;gap:15px;margin:12px 0;flex-wrap:wrap"><?php foreach(['edge_top'=>'Superior','edge_bottom'=>'Inferior','edge_left'=>'Esquerda','edge_right'=>'Direita'] as $k=>$v):?><label class="hint" style="margin:0"><input type="checkbox" name="<?=e($k)?>" value="1"> <?=e($v)?></label><?php endforeach;?></div><button class="btn-aurora" style="margin-top:13px"><?=svg_icon('plus',15)?> Adicionar peça</button></form><?php else:?><p class="hint">Seu perfil não permite editar peças.</p><?php endif;?></div></div>
<?php if($plan):?><div class="panel panel-pad"><div style="display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap"><div><h2>Plano de corte estimado</h2><p class="hint">Método de prateleiras · Serra 3,2 mm · Considera rotação apenas para peças de veio livre</p></div><div style="display:flex;gap:13px"><span class="tag"><?=count($plan['boards'])?> chapa(s)</span><span class="tag">Aproveitamento: <?=e(number_format($plan['utilization'],1,',','.'))?>%</span></div></div>
<?php foreach($plan['boards'] as $idx=>$cutBoard):?><div class="cut-board"><div style="display:flex;justify-content:space-between;gap:10px;margin-bottom:11px"><strong>Chapa <?=($idx+1)?></strong><span class="hint"><?=count($cutBoard['pieces'])?> peça(s) · <?=e(qty($board['width_mm']))?> × <?=e(qty($board['height_mm']))?> mm</span></div><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 <?=e($board['width_mm'])?> <?=e($board['height_mm'])?>" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Distribuição estimada das peças"><rect class="frame" x="0" y="0" width="<?=e($board['width_mm'])?>" height="<?=e($board['height_mm'])?>"/>
<?php foreach($cutBoard['pieces'] as $idx2=>$piece):?><g><rect class="cutpiece" x="<?=e($piece['x'])?>" y="<?=e($piece['y'])?>" width="<?=e($piece['w'])?>" height="<?=e($piece['h'])?>"/><text x="<?=e($piece['x']+$piece['w']/2)?>" y="<?=e($piece['y']+$piece['h']/2)?>" text-anchor="middle" dominant-baseline="middle" style="font-size:<?=max(12,min(35,(float)$piece['w']/9))?>px"><?=e(mb_safe_trim($piece['label'],20))?></text></g><?php endforeach;?></svg></div><?php endforeach;?>
<?php if($plan['unplaced']):?><div class="notice notice-danger"><?=svg_icon('alert')?> <?=count($plan['unplaced'])?> peça(s) não cabem na chapa selecionada. Revise medidas e sentido do veio.</div><?php endif;?><p class="hint">IMPORTANTE: este é um cálculo heurístico de aproveitamento para planejamento, sem consideração de pinças, esquadrejamento, defeitos, tolerâncias ou restrições específicas de máquinas. Confira tecnicamente antes de executar cortes reais.</p></div><?php endif;?>
<?php endif;?>
